// Regenerates www/pl7-shadbala.js (browser build) from shadbala.js (source of truth).
// Usage: node tools/build-www-shadbala.js
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const src = fs.readFileSync(path.join(root, 'shadbala.js'), 'utf8');
const out = "/* Browser build of shadbala.js (standalone Shadbala module), wrapped so its top-level names cannot collide with index.html.\n" +
  " * GENERATED by tools/build-www-shadbala.js from shadbala.js - edit shadbala.js, not this file. */\n" +
  "(function (root) {\n" + src + "\n\nif (root) root.Shadbala = shadbalaExports;\n})(typeof window !== 'undefined' ? window : null);\n";
fs.writeFileSync(path.join(root, 'www', 'pl7-shadbala.js'), out);
console.log('wrote www/pl7-shadbala.js', out.length, 'bytes');
